def align_status_with_is_active(apps, schema_editor):
    """Keep the new ``status`` column consistent with the legacy flag.

    The stores created before the lifecycle engine only had ``is_active``.
    A store that was already offline must not come back online with the
    new default status: it is marked as suspended.
    """
    Store = apps.get_model("catalog", "Store")
    # The historical model does not carry the class constants: the
    # values are spelled out here.
    Store.objects.filter(is_active=False).exclude(
        status="SUSPENDED"
    ).update(status="SUSPENDED")
    # The flagship owns the root of the site: it is always operational.
    Store.objects.filter(is_platform_default=True).update(
        is_active=True, status="ACTIVE"
    )


